import 'package:flutter/material.dart';
import '../utils/gold_formulas.dart';
import '../widgets/number_input.dart';
class KaratConverterScreen extends StatefulWidget{const KaratConverterScreen({super.key});@override State<KaratConverterScreen> createState()=>_KaratConverterScreenState();}
class _KaratConverterScreenState extends State<KaratConverterScreen>{final weight=TextEditingController(),from=TextEditingController(text:'18'),to=TextEditingController(text:'24');double result=0;void calculate(){setState(()=>result=GoldFormulas.convertKarat(weight:double.tryParse(weight.text)??0,fromKarat:double.tryParse(from.text)??0,toKarat:double.tryParse(to.text)??0));}@override void dispose(){weight.dispose();from.dispose();to.dispose();super.dispose();}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('تبدیل عیار')),body:ListView(padding:const EdgeInsets.all(20),children:[const Text('تبدیل وزن بر اساس عیار',style:TextStyle(fontSize:18,fontWeight:FontWeight.w800)),const SizedBox(height:14),NumberInput(controller:weight,label:'وزن',suffix:'گرم'),const SizedBox(height:12),NumberInput(controller:from,label:'عیار مبدأ',suffix:'عیار',decimal:false),const SizedBox(height:12),NumberInput(controller:to,label:'عیار مقصد',suffix:'عیار',decimal:false),const SizedBox(height:18),FilledButton.icon(onPressed:calculate,icon:const Icon(Icons.swap_vert_rounded),label:const Text('تبدیل')),if(result>0)...[const SizedBox(height:20),Card(elevation:0,color:const Color(0xFFFFF9EA),child:Padding(padding:const EdgeInsets.all(22),child:Column(children:[const Text('وزن معادل'),const SizedBox(height:8),Text('${result.toStringAsFixed(3)} گرم',style:const TextStyle(fontSize:25,fontWeight:FontWeight.w900,color:Color(0xFF9A7322)))])))] ]));}
